-- Four additions for the console redesign, none of which changes a decision
-- authorize() or the gate makes today:
--
-- 1. applications.sign_in: who may sign in to an app at all. 'anyone' is
--    every app's behaviour until now and stays the default.
-- 2. permissions.module: a label grouping an app's permissions into modules
--    (Payables, Receivables). Never part of a key; '' until a manifest says.
-- 3. tenants.parent_id: a group of companies, for ADMINISTRATION. An operator
--    assigned to a parent runs the companies below it. Access inside each
--    company stays that company's alone. tenants_tree_guard keeps it a tree.
-- 4. grant_changes and grant_change_items: a bulk change to many grants as
--    one recorded act, with each grant's before and after, so it can be
--    reviewed and undone as the single decision it was.

ALTER TABLE "applications" ADD COLUMN "sign_in" text DEFAULT 'anyone'::text NOT NULL;
ALTER TABLE "applications" ADD CONSTRAINT "applications_sign_in_check" CHECK (sign_in = ANY (ARRAY['anyone'::text, 'role_holders'::text]));
CREATE TABLE "grant_change_items" (
    "change_id" uuid NOT NULL,
    "grant_id" uuid NOT NULL,
    "tenant_id" uuid NOT NULL,
    "before" jsonb NOT NULL,
    "after" jsonb NOT NULL,
    PRIMARY KEY ("change_id", "grant_id")
);
CREATE INDEX "grant_change_items_grant" ON "grant_change_items" ("grant_id");
CREATE TABLE "grant_changes" (
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "undone_at" timestamptz,
    "id" uuid DEFAULT uuidv7() NOT NULL,
    "tenant_id" uuid NOT NULL,
    "actor_id" uuid NOT NULL,
    "undone_by" uuid,
    "kind" text NOT NULL,
    "reason" text DEFAULT ''::text NOT NULL,
    "summary" jsonb DEFAULT '{}'::jsonb NOT NULL,
    "grants" int4 DEFAULT 0 NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "grant_changes_id_tenant_id_key" UNIQUE ("id", "tenant_id"),
    CONSTRAINT "grant_changes_kind_check" CHECK (kind = ANY (ARRAY['add_place'::text, 'remove_place'::text, 'swap_place'::text, 'grow'::text, 'set_until'::text, 'revoke'::text]))
);
CREATE INDEX "grant_changes_tenant_recent" ON "grant_changes" ("tenant_id", "created_at" DESC);
ALTER TABLE "permissions" ADD COLUMN "module" text DEFAULT ''::text NOT NULL;
ALTER TABLE "tenants" ADD COLUMN "parent_id" uuid;
ALTER TABLE "tenants" ADD CONSTRAINT "tenants_parent_check" CHECK (parent_id <> id);
ALTER TABLE "tenants" ADD CONSTRAINT "tenants_parent_id_fkey" FOREIGN KEY ("parent_id") REFERENCES "tenants" ("id") ON DELETE RESTRICT;
CREATE INDEX "tenants_parent" ON "tenants" ("parent_id") WHERE parent_id IS NOT NULL;
ALTER TABLE "grant_change_items" ADD CONSTRAINT "grant_change_items_change_id_tenant_id_fkey" FOREIGN KEY ("change_id", "tenant_id") REFERENCES "grant_changes" ("id", "tenant_id") ON DELETE CASCADE;
ALTER TABLE "grant_change_items" ADD CONSTRAINT "grant_change_items_grant_id_tenant_id_fkey" FOREIGN KEY ("grant_id", "tenant_id") REFERENCES "grants" ("id", "tenant_id") ON DELETE CASCADE;
ALTER TABLE "grant_changes" ADD CONSTRAINT "grant_changes_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON DELETE CASCADE;
CREATE OR REPLACE FUNCTION "trg_tenant_tree_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $storm$
DECLARE
    v_at    uuid := NEW.parent_id;
    v_depth int  := 1;
BEGIN
    IF NEW.parent_id IS NULL THEN RETURN NEW; END IF;
    PERFORM pg_advisory_xact_lock(hashtext('anubis.tenants.tree'));
    WHILE v_at IS NOT NULL LOOP
        IF v_at = NEW.id THEN
            RAISE EXCEPTION 'a company cannot sit under itself or under a company it owns'
                  USING ERRCODE = 'check_violation';
        END IF;
        v_depth := v_depth + 1;
        IF v_depth > 6 THEN
            RAISE EXCEPTION 'companies nest at most 6 levels deep'
                  USING ERRCODE = 'check_violation';
        END IF;
        SELECT parent_id INTO v_at FROM tenants WHERE id = v_at;
    END LOOP;
    -- The subtree that moves with NEW keeps its own depth below it.
    IF v_depth + COALESCE((
         WITH RECURSIVE below(id, d) AS (
             SELECT id, 1 FROM tenants WHERE parent_id = NEW.id
             UNION ALL
             SELECT t.id, b.d + 1 FROM tenants t JOIN below b ON t.parent_id = b.id
              WHERE b.d < 7)
         SELECT max(d) FROM below), 0) > 6 THEN
        RAISE EXCEPTION 'companies nest at most 6 levels deep'
              USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$storm$;
CREATE TRIGGER tenants_tree_guard BEFORE INSERT OR UPDATE OF parent_id ON tenants FOR EACH ROW EXECUTE FUNCTION trg_tenant_tree_guard();
